import {createRacer} from './engine.mjs';
import {mountFlightControls} from './flight-controls.mjs';
const host=window.KFBAudioSite,box=document.createElement('section');box.className='panel';box.id='racer';box.innerHTML=`<style>#racer .vr-row{display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin:12px 0}#racer label{display:grid;gap:5px}#racer .vr-speed{min-width:240px;flex:1}#vr-hud{font-size:23px;padding:16px;background:#17252c;border-radius:12px;color:#edd6a9}#vr-data{max-height:350px;overflow:auto;white-space:pre-wrap}</style><div class="eyebrow">KFB AUDIO · PRIVATER DROPBOX-BESTAND · R1</div><h2>RACER</h2><p class="tiny">Ein Motor, vier Gänge. Flug und Hyperdrive nutzen denselben Audiokontext. Start zunächst ohne Musik.</p><div id="vr-hud">Gestoppt · Gang 1 · 900 RPM</div><div class="vr-row"><button class="btn primary" id="vr-start">Motor starten</button><button class="btn" id="vr-stop">Stop / Reset</button><button class="btn" id="vr-accel">Beschleunigen</button><button class="btn" id="vr-brake">Bremsen</button><button class="btn" id="vr-demo">20-s-Demo</button></div><div class="vr-row"><label class="vr-speed">Tempo <output id="vr-speed-out">0 km/h</output><input id="vr-speed" type="range" min="0" max="180" step="1" value="0"></label><label>Modus<select id="vr-mode"><option value="drive">Racer</option><option value="prop">Propeller</option><option value="jet">Jet</option><option value="jetpack">Jetpack</option><option value="turbine">Turbine</option><option value="antigrav">Antigrav</option><option value="hyperdrive">Hyperdrive-Tunnel</option></select></label><label>Last<input id="vr-throttle" type="range" min="0" max="1" step=".01" value=".7"></label></div><div class="vr-row"><button class="btn" data-vr-event="boost">Boost</button><button class="btn" data-vr-event="takeoff">Abheben</button><button class="btn" data-vr-event="charge">HD laden</button><button class="btn" data-vr-event="jump">HD Sprung</button><button class="btn" data-vr-event="exit">HD Austritt</button><button class="btn" id="vr-music">Musik: aus</button><button class="btn" id="vr-focus">Sprachfokus: aus</button></div><output id="vr-status" aria-live="polite">Gestoppt · keine Generierung, keine öffentlichen Audiodateien.</output><div class="vr-row"><a id="vr-recording" hidden>20-s-Aufnahme herunterladen</a></div><details><summary>Abstimmung, Referenzen und Messungen</summary><p class="tiny">Die höhere Drehzahl wurde aus gemessenen Tonhöhen vorab abgestimmt. Das ist ein Kandidat, keine Hörabnahme. Original zum A/B bleibt auswählbar.</p><label><input type="checkbox" id="vr-tuned" checked> Gemessene Abstimmung verwenden</label><div class="vr-row"><button class="btn" data-vr-ref="S1_accel_upshifts">Referenz S1 · 3 Gänge</button><button class="btn" data-vr-ref="S2_brake_downshifts">Referenz S2 · Bremsen</button></div><pre id="vr-data"></pre><a href="./racer/CONSUMER.md" target="_blank">Audio-Anschluss &amp; Quellen</a></details>`;
document.querySelector('#soundscape').prepend(box);const shortcut=document.createElement('button');shortcut.id='vr-shortcut';shortcut.textContent='Racer';shortcut.onclick=()=>{document.querySelector('[data-view="soundscape"]').click();box.scrollIntoView({block:'start'});};document.querySelector('.tabs').append(shortcut);
const $=id=>box.querySelector('#'+id);let engine,init,run=0,music=false,musicRun=0,focusOwned=false,paintAt=-1,wasActive=false,recorder,capture,chunks=[],clipUrl,flight;
async function ensure(){if(engine)return engine;if(init)return init;init=(async()=>{const g=await host.resume();engine=await createRacer({audioContext:g.ctx,destination:g.buses.PLAYER_CRITICAL});return engine;})().finally(()=>init=null);return init;}
const status=t=>$('vr-status').textContent=t;
async function start(action='manual'){flight?.cancel();const token=++run;$('vr-start').disabled=true;status('Private Aufnahmen werden geprüft und decodiert …');try{const e=await ensure();if(token!==run)return;await e.start();if(token!==run)return;e.control(action);e.setTelemetry({mode:action==='demo'?'drive':$('vr-mode').value,throttle:action==='demo'?0:Number($('vr-throttle').value)});if(action==='demo'){e.setTelemetry({engineOn:true,geared:false,bank:0,vertical:0,airbrake:0});record();}else flight?.applyManual();status(action==='demo'?'20 Sekunden · Leerlauf → 3 Hochschaltungen → Bremsen / Schubknallen':'Läuft · Hörabnahme offen.');}catch(err){if(token!==run)return;engine?.stop();status('Nicht gestartet: '+err.message);}finally{$('vr-start').disabled=false;paint();}}
function finishRecording(){if(recorder?.state==='recording')recorder.stop();capture?.disconnect();capture=null;}
function record(){finishRecording();if(!('MediaRecorder' in window))return;try{capture=engine.createCapture();const type=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(capture.stream,type?{mimeType:type}:{});const chunks=[],current=recorder;current.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};current.onstop=()=>{if(clipUrl)URL.revokeObjectURL(clipUrl);clipUrl=URL.createObjectURL(new Blob(chunks,{type:current.mimeType}));$('vr-recording').href=clipUrl;$('vr-recording').download='kfb-racer-gears-r1-demo.'+(current.mimeType.includes('mp4')?'m4a':'webm');$('vr-recording').hidden=false;};current.start();}catch(e){status('Demo läuft; Aufnahme nicht verfügbar: '+e.message);}}
function stop(){flight?.cancel();run++;musicRun++;engine?.stop();finishRecording();if(music)host.adaptiveMusic.stop();music=false;if(focusOwned)host.musicContext.setVoiceActive(false,{source:'racer-stop'});focusOwned=false;$('vr-focus').textContent='Sprachfokus: aus';$('vr-music').textContent='Musik: aus';$('vr-speed').value=0;status('Gestoppt · alle Motor-/Flug-/HD-Stimmen beendet.');paint();}
function paint(){if(!engine)return;const s=engine.snapshot(),t=host.audioContext.currentTime;if(wasActive&&!s.active){finishRecording();status('Demo beendet · gestoppt.');}wasActive=s.active;if(t-paintAt<.1&&s.active)return;paintAt=t;$('vr-hud').textContent=(s.active?'Läuft':'Gestoppt')+' · Gang '+s.gear+' · '+Math.round(s.rpm)+' RPM · '+Math.round(s.speedKmh)+' km/h';$('vr-speed-out').textContent=Math.round(s.speedKmh)+' km/h';if(s.driveMode!=='manual')$('vr-speed').value=s.speedKmh;$('vr-data').textContent=JSON.stringify({revision:'0.10.0',hostContexts:host.audioContextsCreated,...s,events:s.events.slice(-40)},null,2);}
host.registerAudioTick(()=>{flight?.tick();if(!engine)return;engine.setMix(host.getMixActivity());engine.tick();paint();});
$('vr-start').onclick=()=>start();$('vr-stop').onclick=stop;$('vr-accel').onclick=()=>start('accelerate');$('vr-brake').onclick=()=>start('brake');$('vr-demo').onclick=()=>start('demo');
$('vr-speed').oninput=()=>{if(!engine)return;engine.control('manual');engine.setTelemetry({speedKmh:Number($('vr-speed').value),throttle:Number($('vr-throttle').value),brake:0});};$('vr-throttle').oninput=()=>engine?.setTelemetry({throttle:Number($('vr-throttle').value)});$('vr-mode').onchange=()=>{if(!engine)return;engine.control('manual');engine.setTelemetry({mode:$('vr-mode').value,throttle:Number($('vr-throttle').value)});};$('vr-tuned').onchange=()=>engine?.setTuned($('vr-tuned').checked);
box.querySelectorAll('[data-vr-event]').forEach(b=>b.onclick=async()=>{await start();engine?.emit({type:b.dataset.vrEvent})});box.querySelectorAll('[data-vr-ref]').forEach(b=>b.onclick=async()=>{await start();engine?.auditionReference(b.dataset.vrRef)});
$('vr-music').onclick=async()=>{const token=++musicRun;try{if(music){host.adaptiveMusic.stop();music=false;}else{status('Bestehende Musik wird geladen …');await host.adaptiveMusic.startDeck('D');if(token!==musicRun){host.adaptiveMusic.stop();return;}music=true;}$('vr-music').textContent='Musik: '+(music?'an':'aus');}catch(e){status(e.message);}};$('vr-focus').onclick=()=>{focusOwned=!focusOwned;host.musicContext.setVoiceActive(focusOwned,{source:'racer-focus-test'});$('vr-focus').textContent='Sprachfokus: '+(focusOwned?'an':'aus');};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop);host.racer={getSnapshot:()=>engine?.snapshot()||{active:false},setTelemetry:update=>engine?.setTelemetry(update),stop};flight=mountFlightControls({host,box,ensureRacer:ensure,stopRacer:stop});if(location.hash==='#racer')shortcut.click();
